#!/usr/bin/env -S deno run -A
//MISE description="Devsy の設定と adapter による VM・接続の一括操作"
//MISE quiet=true
//MISE raw=true
//MISE raw_args=true

import { resolve } from "@std/path";
import { $ } from "../mod.ts";
import { assertAgentKeyFile } from "./bootstrap.ts";
import { readPermanKeyringAuth } from "../lib/perman-auth.ts";
import { diagnosticLog, sanitizeDiagnostic } from "../lib/setup-diagnostics.ts";

const reportedErrors = new WeakSet<object>();

export async function readDevsyCommand(
  file = $.paths.repo.root.join("orca.yaml").toString(),
): Promise<[string, ...string[]]> {
  const output = await new Deno.Command("yq", {
    args: ["-o=json", ".devsy.command", file],
    stdout: "piped",
    stderr: "piped",
  }).output();
  if (!output.success) throw new Error("Cannot read orca.yaml devsy.command");
  const command: unknown = JSON.parse(new TextDecoder().decode(output.stdout));
  if (
    !Array.isArray(command) || command.length === 0 ||
    !command.every((arg: unknown) => typeof arg === "string")
  ) throw new Error("orca.yaml devsy.command must be a nonempty string array");
  const expanded = (command as string[]).map((arg) =>
    arg.replace(
      /\$\{([^}]*)(\}|$)/g,
      (_match, reference: string, end: string) => {
        const required = reference.endsWith("?");
        const name = required ? reference.slice(0, -1) : reference;
        if (!end || !/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(name)) {
          throw new Error("Invalid variable in orca.yaml devsy.command");
        }
        const value = name === "ORCA_REPO_PATH"
          ? $.paths.repo.root.toString()
          : Deno.env.get(name);
        if (required && value === undefined) {
          throw new Error(`orca.yaml devsy.command requires ${name}`);
        }
        return value ?? "";
      },
    )
  );
  if (!expanded[0]) {
    throw new Error("Invalid orca.yaml devsy.command");
  }
  return [expanded[0], ...expanded.slice(1)];
}

function record(value: unknown): Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error("Expected JSON object");
  }
  return value as Record<string, unknown>;
}
function lines(
  consume: (line: string) => void,
  limit?: number,
): WritableStream<Uint8Array> {
  const decoder = new TextDecoder();
  let buffer = "";
  let discarding = false;
  const consumeLine = (line: string) =>
    consume(
      limit !== undefined && line.length > limit
        ? "[oversized log line omitted]"
        : line,
    );
  return new WritableStream({
    write(chunk) {
      buffer += decoder.decode(chunk, { stream: true });
      let newline;
      while ((newline = buffer.search(/[\r\n]/)) >= 0) {
        if (!discarding) consumeLine(buffer.slice(0, newline));
        discarding = false;
        buffer = buffer.slice(newline + 1);
      }
      if (limit !== undefined && buffer.length > limit) {
        if (!discarding) consume("[oversized log line omitted]");
        discarding = true;
        buffer = "";
      }
    },
    close() {
      if (!discarding) consumeLine(buffer + decoder.decode());
    },
  });
}

const configureInputs = {
  readAgentKey: async (): Promise<string> => {
    const file = resolve(
      import.meta.dirname ?? ".",
      "../../.local/state/agent/age.key",
    );
